let save={...DEFAULT_SAVE};let storage=true;try{save=migrateSave(JSON.parse(localStorage.getItem('emberhold-v1')||'null'));}catch{storage=false;}
function persist(){try{localStorage.setItem('emberhold-v1',JSON.stringify(save));return true;}catch{storage=false;toast('לא ניתן לשמור במכשיר כרגע. ההתקדמות זמינה עד סגירת המשחק.');return false;}}
