function portrait(i,cls=''){const h=HEROES[i],actual=portraitCache.get(h.id);if(actual)return `<img class="portrait model-portrait ${cls}" src="${actual}" alt="${h.name}">`;if(h.look)return `<span class="portrait sigil-portrait ${cls}" style="--accent:${h.color}" role="img" aria-label="${h.name}">${h.symbol}</span>`;return h.portrait?`<img class="portrait custom-portrait ${cls}" src="${h.portrait}" alt="${h.name}">`:`<span class="portrait ${cls}" style="--pos:${positions[h.rig]}" role="img" aria-label="${h.name}"></span>`}

function navigate(page){
 if(game&&game.state==='playing')return;
 $('collection').classList.add('hidden');if(page==='collection'){closeModal();game=null;document.body.classList.remove('in-battle');$('battle').classList.add('hidden');$('lobby').classList.add('hidden');$('shop').classList.add('hidden');$('collection').classList.remove('hidden');renderCollection();document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===page?'page':'false'));return;}if(page==='battle'){showHome();return;}
 closeModal();game=null;document.body.classList.remove('in-battle');$('battle').classList.add('hidden');$('lobby').classList.add('hidden');$('shop').classList.remove('hidden');heroDetail=false;shopTab=page==='heroes'?'heroes':'general';lobby();window.scrollTo(0,0);
 document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===page?'page':'false'));
}
