function lobby(){
 $('bank').textContent='◈ '+save.coins;$('bestWave').textContent='גל '+save.best+' מתוך 10';const rank=careerProgress(save.careerXp);$('careerLevel').textContent='רמת מפקד '+rank.level;$('careerText').textContent=rank.xp+' / '+rank.needed+' XP';$('careerBar').style.width=rank.percent+'%';
 $('shopTabs').innerHTML=`<button data-tab="general" aria-pressed="${shopTab==='general'}">◇ שדרוגים כלליים</button><button data-tab="heroes" aria-pressed="${shopTab==='heroes'}">✦ הכשרת גיבורים</button>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{shopTab=b.dataset.tab;heroDetail=false;lobby()});
 $('shopHeroes').classList.toggle('hidden',shopTab!=='heroes'||heroDetail);
 $('shopHeroes').innerHTML=shopTab==='heroes'?HEROES.map((h,i)=>{const p=heroProgress(save,h.id);return `<button data-shophero="${i}" style="--accent:${h.color}">${portrait(i)}<b>${h.name}</b><small>${h.role} · ${ownsHero(save,h.id)?'רמה '+p.level:'נעול · '+(save.collection?.heroes?.[h.id]?.cards||0)+'/'+unlockCost(h)+' קלפים'}</small><span class="mastery-track"><i style="width:${p.percent}%"></i></span><small>${p.level===20?'שליטה מלאה':p.xp+' / '+p.needed+' XP'} · תעודת גיבור ←</small></button>`}).join(''):'';document.querySelectorAll('[data-shophero]').forEach(b=>b.onclick=()=>{shopHero=+b.dataset.shophero;heroDetail=true;heroAngle=0;lobby();$('heroDetailBack').focus()});
 $('research').classList.toggle('hidden',shopTab==='heroes'&&(!heroDetail||!ownsHero(save,HEROES[shopHero].id)));
 $('research').innerHTML=SHOP.filter(d=>d.group===shopTab&&(shopTab==='general'||d.hero===shopHero)).map(d=>{const lv=save[d.key],cost=Math.round(d.base*1.65**lv),max=lv>=8;return `<article class="shop-card">${d.hero===undefined?`<div class="shop-emblem">${d.icon}</div>`:`<div class="shop-portrait">${portrait(d.hero)}</div>`}<span class="badge">קבוע · דרגה ${lv} / 8</span><h2>${d.name}</h2><p>${d.desc}</p><div class="skill-nodes" aria-label="${lv} מתוך 8 דרגות">${Array.from({length:8},(_,i)=>`<i class="${i<lv?'unlocked':''}"></i>`).join('')}</div><div class="comparison"><span><small>עכשיו</small>${d.value(lv)} ${d.unit}</span><span><small>${max?'מקסימום':'אחרי השדרוג'}</small>${d.value(max?lv:lv+1)} ${d.unit}</span></div><button class="primary" data-buy="${d.key}" ${save.coins<cost||max?'disabled':''}>${max?'שודרג למקסימום':'שדרוג · ◈ '+cost}</button>${!max&&save.coins<cost?`<small class="shortfall">חסרים ${cost-save.coins} מטבעות</small>`:''}</article>`}).join('');
 document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{if(buyUpgrade(save,b.dataset.buy)){persist();sfx.play('recruit');lobby();toast('ההכשרה התחזקה ונשמרה לכל הריצות')}});
 const hero=HEROES[shopHero],owned=ownsHero(save,hero.id),card=save.collection?.heroes?.[hero.id],previewMeta={...save,collection:{...save.collection,heroes:{...save.collection?.heroes,[hero.id]:{...card,unlocked:true}}}},trained=new Game({hero:shopHero,meta:previewMeta}).team[0];
 $('heroShowcase').classList.toggle('hidden',shopTab!=='heroes'||!heroDetail);
 if(shopTab==='heroes'&&heroDetail&&!$('shop').classList.contains('hidden')){const p=heroProgress(save,hero.id),gadget=GADGETS[hero.archetype];$('heroShowcase').innerHTML=`<button id="heroDetailBack" class="text-button">→ כל הגיבורים</button><div class="hero-viewer" id="heroViewer" tabindex="0" role="img" aria-label="מודל ${hero.name}. גרירה אופקית או מקשי חצים לסיבוב.">${view3d?'':portrait(shopHero)}</div><div class="viewer-controls">${view3d?'<button id="rotateLeft" aria-label="סיבוב שמאלה">↶</button><span>גררו לסיבוב · אפשר גם עם החצים</span><button id="rotateRight" aria-label="סיבוב ימינה">↷</button>':'<span>תצוגת תמונה · תלת־ממד אינו זמין בדפדפן הזה</span>'}</div><div class="hero-dossier"><span class="eyebrow">${hero.role} · רמת גיבור ${p.level}</span><h2>${hero.name}</h2><p>${owned?'גיבור זמין':'נעול · נפתח באיסוף '+unlockCost(hero)+' קלפים מתיבות'}</p><p>${hero.desc}</p><div class="mastery-track"><i style="width:${p.percent}%"></i></div><p>${p.level===20?'שליטה מלאה':p.xp+' / '+p.needed+' XP לרמה הבאה'} · בונוס פתיחה: ${p.bonus}% נזק</p><small>ניסיון מקרבות, זמן לחימה והכשרות קבועות. ${Math.floor(p.seconds/60)} דקות לחימה · ${p.score} ניקוד מצטבר</small><div class="identity-equipment"><article><small>נשק ראשי</small><h3>${hero.weapon}</h3><b>${Math.round(trained.damage)} נזק · ${trained.interval.toFixed(2)} שנ׳ בין מתקפות</b></article><article><small>כוח ייחודי</small><h3>${hero.special}</h3><p>${hero.desc}</p></article><article><small>${p.level>=2?'זמין לבחירה בריצה':'נפתח ברמת גיבור 2'}</small><h3>${gadget.name}</h3><p>${gadget.desc}.</p><p>רמה 2: דרגת גאדג׳ט אחת בריצה. רמה 4: עד שלוש דרגות. בוחרים ומשדרגים באמצעות עליות רמת הריצה.</p></article></div><article class="power-description"><small>כוח ידני · הגיבור המוביל בריצה</small><h3>${TACTICAL_POWERS[hero.archetype].name}</h3><p>${TACTICAL_POWERS[hero.archetype].desc}</p><small>נטען אחרי 8 חיסולים בהפעלה הראשונה, ואז בכל 14 חיסולים.</small></article><div class="hero-card-training"><h3>קלפי גיבור · דרגה ${heroCardRank(save,hero.id)} / 5</h3><p>${card?.cards||0} קלפים · כל דרגה מוסיפה 6% נזק התחלתי וניסיון שליטה.</p><button id="upgradeHeroCards" class="secondary" ${!owned||heroCardRank(save,hero.id)>=5||(card?.cards||0)<(heroCardRank(save,hero.id)+1)*4?'disabled':''}>שדרוג · ${(heroCardRank(save,hero.id)+1)*4} קלפים</button></div><h3>הכשרות קבועות</h3></div>`;
 $('upgradeHeroCards').onclick=()=>{if(upgradeCards(save,'heroes',hero.id)){persist();lobby();}};
 $('heroDetailBack').onclick=()=>{heroDetail=false;view3d?.attach($('homeScene'));lobby();document.querySelector('[data-shophero="'+shopHero+'"]').focus()};if(view3d){const host=$('heroViewer');view3d.attach(host);let drag=null;host.onpointerdown=e=>{drag={id:e.pointerId,x:e.clientX};host.setPointerCapture(e.pointerId)};host.onpointermove=e=>{if(drag?.id===e.pointerId){heroAngle+=(e.clientX-drag.x)*.015;drag.x=e.clientX}};host.onpointerup=host.onpointercancel=()=>drag=null;host.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();heroAngle+=e.key==='ArrowLeft'?-.25:.25}};$('rotateLeft').onclick=()=>heroAngle-=.4;$('rotateRight').onclick=()=>heroAngle+=.4;}}
 $('shop').querySelector('h1').textContent=shopTab==='heroes'?'הגיבורים שלכם':'לב המצודה';
 $('saveNote').textContent=storage?'הקניות ורמת המפקד נשמרות במכשיר הזה.':'השמירה המקומית אינה זמינה בדפדפן הזה.';
}
function showHome(){$('collection').classList.add('hidden');document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page==='battle'?'page':'false'));closeModal();game=null;document.body.classList.remove('in-battle');$('battle').classList.add('hidden');$('shop').classList.add('hidden');$('lobby').classList.remove('hidden');view3d?.attach($('homeScene'));lobby();window.scrollTo(0,0)}
function chooseStarter(){sfx.unlock();closeModal();const choices=startingChoices(Math.random,save);openModal(`<section class="modal starter-modal"><span class="eyebrow">משחק חדש</span><h2>מי ישמור על הגחלת?</h2><p class="subtitle">שלושה גיבורים נקראו למצודה. בחרו מי יוביל את הריצה.</p><div class="starter-grid">${choices.map(i=>{const h=HEROES[i];return `<button class="starter-card" data-starter="${i}" style="--accent:${h.color}">${portrait(i)}<span class="badge">${h.role}</span><h3>${h.name}</h3><p>${h.desc}</p><span class="choose-label">מתחילים עם ${h.name} ←</span></button>`}).join('')}</div><button id="cancelStart" class="text-button">חזרה לבית</button></section>`);document.querySelectorAll('[data-starter]').forEach(b=>b.onclick=()=>{selectedHero=+b.dataset.starter;start()});$('cancelStart').onclick=showHome;}
function openModal(html){modalPrior=document.activeElement;$('overlay').innerHTML=html;$('overlay').classList.remove('hidden');$('overlay').classList.toggle('over-battle',!!game&&game.state!=='retired');$('app').inert=true;document.body.style.overflow='hidden';const m=$('overlay').querySelector('.modal');m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');m.setAttribute('aria-label',m.querySelector('h2')?.textContent||'תפריט משחק');m.tabIndex=-1;m.focus();}
function closeModal(){$('overlay').classList.remove('hero-inspect');$('overlay').classList.add('hidden');$('overlay').innerHTML='';$('app').inert=false;document.body.style.overflow='';if(modalPrior?.isConnected)modalPrior.focus();}
$('overlay').addEventListener('keydown',e=>{if(e.key!=='Tab')return;let a=[...$('overlay').querySelectorAll('button:not(:disabled)')];if(!a.length)return;if(e.shiftKey&&(document.activeElement===a[0]||document.activeElement.classList.contains('modal'))){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}});
function teamUI(){$('heroHotspots').innerHTML=game.team.map((h,i)=>`<button class="hero-hotspot" data-inspect="${i}" aria-label="מידע ושדרוגים של ${h.name}" style="--accent:${h.color}">${h.name}<i class="charge-track"><i></i></i><small class="charge-label"></small></button>`).join('');document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=e=>{e.stopPropagation();inspectHero(+b.dataset.inspect,b.getBoundingClientRect())});}
function inspectHero(i,rect){if(!game||game.state!=='playing')return;const h=game.team[i];game.state='inspecting';const acquired=[...new Set([...h.upgrades,...game.upgradeLog.filter(u=>u.kind==='צוות')])];openModal(`<section class="modal hero-info"><div class="hero-info-head">${portrait(h.index)}<div><span class="eyebrow">${h.role}</span><h2>${h.name}</h2><span>דרגת ריצה ${h.rank}</span></div></div><p>${h.desc}</p><p class="identity-line">נשק: ${h.weapon}<br>יכולת: ${h.special}</p><div class="hero-stats"><span>נזק לפגיעה <b>${Math.round(h.damage*game.teamDamage)}</b></span><span>${h.archetype==='gunner'?'טעינת מחסנית':'בין מתקפות'} <b>${(h.archetype==='gunner'?h.reload:h.interval).toFixed(2)} שנ׳</b></span><span>${h.archetype==='fire'?'נזק שריפה':h.archetype==='electric'?'מטרות בשרשרת':h.archetype==='frost'?'האטה':'קליעים במחסנית'} <b>${h.archetype==='fire'?h.burn+'/שנ׳':h.archetype==='electric'?h.chain:h.archetype==='frost'?Math.round(h.slow*100)+'%':h.mag}</b></span></div><h3>נאסף בריצה הזאת</h3><div class="acquired">${acquired.length?acquired.map(u=>`<div><b>${u.title}</b><small>${u.kind==='צוות'?'כל הצוות · ':''}${u.after}</small></div>`).join(''):'<p>עדיין לא נאספו שדרוגים. היכולת הבסיסית כבר פעילה.</p>'}</div><button id="closeHero" class="primary">חזרה לקרב</button></section>`);$('overlay').classList.add('hero-inspect');const panel=$('overlay').querySelector('.hero-info');const width=Math.min(330,window.innerWidth-24),height=Math.min(560,window.innerHeight-30);panel.style.width=width+'px';panel.style.maxHeight=height+'px';panel.style.left=Math.max(12,Math.min(window.innerWidth-width-12,rect.left-width/2))+'px';panel.style.bottom=Math.max(15,Math.min(window.innerHeight-height-12,window.innerHeight-rect.top+15))+'px';$('closeHero').onclick=()=>{closeModal();game.state='playing';last=performance.now()};}
function positionHeroes(){if(!game)return;const host=$('battleScene').getBoundingClientRect();const wallY=view3d?view3d.project(250,535,.9).y:535/750*host.height;$('wallHealth').style.top=Math.max(12,Math.min(host.height-34,wallY+56))+'px';$('wallHealth').style.bottom='auto';document.querySelectorAll('[data-inspect]').forEach(b=>{const i=+b.dataset.inspect;const p=view3d?view3d.project(90+i*105,555,.5):{x:(90+i*105)/500*host.width,y:640/750*host.height};b.style.left=p.x+'px';b.style.top=p.y+'px';const h=game.team[i];const reload=h.archetype==='gunner'&&h.reloading;b.classList.toggle('is-reloading',reload);const progress=h.archetype==='frost'?h.specialTimer/h.specialCooldown:1-Math.max(0,h.cd)/(reload?h.reload:h.interval);b.querySelector('.charge-track>i').style.width=Math.max(0,Math.min(1,progress))*100+'%';b.querySelector('.charge-label').textContent=h.archetype==='frost'?'הקפאה '+Math.max(0,Math.ceil(h.specialCooldown-h.specialTimer))+'ש׳':reload?'טוען…':h.archetype==='gunner'?h.ammo+' / '+h.mag:' ';});}
function lootFlight(item){if(!game||document.querySelectorAll('.loot-fly').length>44)return;const host=$('battleScene').getBoundingClientRect(),p=view3d?view3d.project(item.x,item.y,.5):{x:item.x/500*host.width,y:item.y/750*host.height};for(const kind of ['xp','coin',...(item.keys?['key']:[])]){const el=document.createElement('span');el.className='loot-fly '+kind;el.textContent=kind==='xp'?'◆':kind==='key'?'⚿':'◈';el.setAttribute('aria-hidden','true');document.body.append(el);const target=$(kind==='xp'?'xpBar':kind==='key'?'runKeys':'runBag').getBoundingClientRect();const sx=host.left+p.x+(kind==='coin'?-10:10),sy=host.top+p.y,tx=target.left+target.width*.5,ty=target.top+target.height*.5;const a=el.animate([{transform:`translate(${sx}px,${sy}px) scale(1)`,opacity:1},{transform:`translate(${(sx+tx)/2+25}px,${Math.min(sy,ty)-40}px) scale(1.2)`,opacity:1},{transform:`translate(${tx}px,${ty}px) scale(.3)`,opacity:0}],{duration:500,easing:'ease-in',fill:'forwards'});a.playbackRate=speed;a.onfinish=()=>el.remove();}}
function start(){$('collection').classList.add('hidden');closeModal();game=new Game({hero:selectedHero,meta:save});document.body.classList.add('in-battle');$('shop').classList.add('hidden');speed=1;ended=false;history=[];$('lobby').classList.add('hidden');$('battle').classList.remove('hidden');view3d?.attach($('battleScene'));$('speed').textContent='×1';$('history').innerHTML='<p>כאן יופיע הבילד שתיצרו.</p>';noticeUntil=0;$('combatNotice').classList.remove('notice-active');$('combatNotice').textContent='סמנו אויב כדי למקד את הירי';buildPowerSlots();teamUI();hud();window.scrollTo(0,0);tone(520);}
