function buildPowerSlots(){$('supportPowers').innerHTML=Array.from({length:2},(_,i)=>{const s=game.spells[i];return s?`<button class="spell-slot" data-cast="${s.id}" title="${s.desc}" style="--accent:${s.color}"><span>${s.icon}</span><b>${s.name}</b><small>0 / ${s.need}</small></button>`:'<div class="spell-slot empty"><span>♧</span><b>מקום למתקפה</b><small>בחירה באוסף</small></div>'}).join('');document.querySelectorAll('[data-cast]').forEach(b=>b.onclick=()=>{if(game?.activateSpell(b.dataset.cast))hud()});}
function renderCollection(){const c=ensureCollection(save);$('keyBank').textContent='⚿ '+c.keys+' מפתחות';$('chestGrid').innerHTML=CHESTS.map(t=>`<article class="chest-card" style="--accent:${t.color}"><div class="chest-art" aria-hidden="true"><i></i><b>✦</b></div><small>${t.name}</small><h3>${t.label}</h3><p>${t.desc}</p><details><summary>מה אפשר לקבל?</summary><p>הגיבור נבחר בהסתברות שווה מתוך המאגר המתאים לתיבה. המתקפה נבחרת בהסתברות של 25% לכל אחת מארבע המתקפות. באגדית, אם יש דמויות נעולות, הבחירה היא ביניהן בלבד.</p><p>${HEROES.filter(h=>['gunner','fire','electric','frost'].includes(h.id)||t.rarities.includes(h.rarity||'rare')).map(h=>h.name).join(' · ')}</p></details><button class="primary" data-chest="${t.id}" ${c.keys<t.cost?'disabled':''}>פתיחה · ⚿ ${t.cost}</button></article>`).join('');$('spellGrid').innerHTML=SPELLS.map(s=>{const r=c.spells[s.id]||{cards:0,rank:0,unlocked:false},equipped=c.loadout.includes(s.id);return `<article class="spell-card ${r.unlocked?'':'locked'}" style="--accent:${s.color}"><div class="spell-emblem">${s.icon}</div><span>${r.unlocked?'דרגה '+(r.rank+1)+' / 6':'נעול · '+r.cards+' / 3 קלפים'}</span><h3>${s.name}</h3><p>${s.desc}</p><p>טעינה: ${s.need} חיסולים · ${r.cards} קלפים זמינים</p><button data-equip="${s.id}" ${!r.unlocked||(!equipped&&c.loadout.length>=2)?'disabled':''} aria-pressed="${equipped}">${equipped?'✓ מצויד · הסרה':'הוספה לקרב'}</button><button data-spellup="${s.id}" ${!r.unlocked||r.rank>=5||r.cards<(r.rank+1)*4?'disabled':''}>${r.rank>=5?'דרגה מרבית':'שדרוג · '+(r.rank+1)*4+' קלפים'}</button></article>`}).join('');document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{if(toggleSpell(save,b.dataset.equip)){persist();renderCollection()}});document.querySelectorAll('[data-spellup]').forEach(b=>b.onclick=()=>{if(upgradeCards(save,'spells',b.dataset.spellup)){persist();renderCollection()}});document.querySelectorAll('[data-chest]').forEach(b=>b.onclick=()=>revealChest(b.dataset.chest));}
function revealChest(id){const before=migrateSave(save),result=openChest(save,id);if(!result)return;if(!persist()){save=before;toast('התיבה לא נפתחה כי השמירה נכשלה. המפתחות נשארו.');return;}renderCollection();const chest=CHESTS.find(c=>c.id===id);openModal(`<section class="modal chest-opening" style="--accent:${chest.color}"><span class="eyebrow">${chest.name}</span><h2>${chest.label}</h2><div class="chest-art reveal" aria-hidden="true"><i></i><b>✦</b></div><div class="reward-cards">${result.rewards.map((r,i)=>`<article style="--accent:${r.color};--delay:${i*.16}s">${r.kind==='heroes'?portrait(HEROES.findIndex(h=>h.id===r.id)):'<span class="spell-emblem">'+SPELLS.find(s=>s.id===r.id).icon+'</span>'}<small>${r.unlocked?'נפתח עכשיו!':r.kind==='heroes'?'קלפי גיבור':'קלפי מתקפה'}</small><h3>${r.name}</h3><b>+${r.amount} קלפים</b></article>`).join('')}</div><p>הפרסים נשמרו. קלפים שנדרשו לפתיחה כבר הומרו לפתיחת הדמות או המתקפה.</p><button class="primary" id="closeChest">לאוסף שלי</button></section>`);$('closeChest').onclick=()=>{closeModal();renderCollection()};sfx.play('chest');}
let weatherTick=-1;const israelClock=new Intl.DateTimeFormat('he-IL',{timeZone:'Asia/Jerusalem',hour:'2-digit',minute:'2-digit'});
function loop(now){if(now-weatherTick>10000||weatherTick<0){weatherTick=now;const climate=view3d?.environment?.atmosphere;const text=climate?israelClock.format(new Date())+' · '+climate.label+' (מזג מדומה)':'';$('homeWeather').textContent=text;$('battleWeather').textContent=climate?israelClock.format(new Date())+' · '+climate.label:'';$('battleWeather').title='שעון ישראל · תאורה למרכז הארץ · מזג אוויר מדומה';}let real=Math.min(.05,(now-last)/1000||0);last=now;if(game){if(game.state==='playing'){for(let n=0;n<speed;n++)game.step(real);}for(const e of game.events.splice(0)){if(e.type==='attack'){const member=game.team[Math.round(((e.pan||0)+.65)/.43)];sfx.play(member?.id==='briar'?'nature':e.hero,e.pan);}if(e.type==='reloadStart')sfx.play('reloadStart',e.pan);if(e.type==='reloadEnd')sfx.play('reloadEnd',e.pan);if(e.type==='powerReady'){sfx.play('ready');combatNotice((e.leader?TACTICAL_POWERS[game.team[0].archetype].name:e.name)+' מוכן להפעלה');}if(e.type==='impact')sfx.play(e.presentation?.special?'heavy-'+(e.presentation.heroId||e.hero):'impact-'+soundIdentity(e.presentation?.heroId,e.hero));if(e.type==='wallHit')sfx.play('wall');if(e.type==='death')sfx.play(e.boss?'boom':'break-'+soundIdentity(e.presentation?.heroId,e.hero));if(e.type==='ability')sfx.play('shield');if(e.type==='special')sfx.play(e.presentation?.special>=2?'special-'+e.presentation.heroId:e.hero);if(e.type==='shockwaveCharge')sfx.play('shockwave-charge');if(e.type==='shockwaveRelease')sfx.play('shockwave');if(e.type==='lootFlight')lootFlight(e);if(e.type==='lootCollected'){if(e.keys){sfx.play('key');combatNotice('⚿ נאספו '+e.keys+' מפתחות לתיבות');}else sfx.play('loot');$('xpBar').classList.remove('collect-pulse');void $('xpBar').offsetWidth;$('xpBar').classList.add('collect-pulse');$('runBag').classList.add('collect-pulse');setTimeout(()=>$('runBag').classList.remove('collect-pulse'),220);}if(e.type==='level'){sfx.play('level');showChoices();}if(e.type==='upgrade'){sfx.play(e.recruit?'recruit':'level');history.unshift(e);$('history').innerHTML=history.map(v=>`<div>${v.title}<small>${v.who}</small></div>`).join('');toast(e.who+' · '+e.title)}if(e.type==='wave'){$('waveBanner').textContent=[3,6,10].includes(e.wave)?'גל '+e.wave+' · בוס מתקרב':'גל '+e.wave;$('waveBanner').classList.add('show');clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>$('waveBanner').classList.remove('show'),2100);tone(280,.2)}if(e.type==='boss'){sfx.play('boss');$('waveBanner').textContent=e.name+' · בוס בגל '+game.wave;$('waveBanner').classList.add('show');clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>$('waveBanner').classList.remove('show'),2600);tone(160,.35)}if(e.type==='end')finish();}if(!view3d)draw(now);if(now-uiTick>100){hud();uiTick=now;}}sfx.update?.({state:game?.state==='playing'&&game.intermission>0?'calm':game?.state||'calm',boss:!!game?.enemies.some(e=>e.isBoss),intensity:Math.min(1,(game?.enemies.length||0)/24),rain:view3d?.environment?.atmosphere?.rain||0,paused:document.hidden||game?.state==='paused'});for(const el of document.querySelectorAll('.loot-fly'))for(const a of el.getAnimations()){a.playbackRate=speed;if(game?.state==='playing')a.play();else a.pause();}if(view3d){if($('shop').classList.contains('hidden')&&$('collection').classList.contains('hidden'))view3d.render(game,now);else if(shopTab==='heroes'&&heroDetail)view3d.renderHero(shopHero,heroAngle,now);}requestAnimationFrame(loop)}
Promise.all([bg.decode(),ha.decode(),ea.decode()]).then(()=>{makeSprites(ha,'h');makeSprites(ea,'e');$('start').disabled=false;$('start').innerHTML='משחק חדש <span>←</span>';}).catch(()=>{$('start').disabled=false;$('start').textContent='טעינת הזירה מחדש';$('start').onclick=()=>location.reload();toast('חלק מהתמונות לא נטענו. לחצו כדי לנסות שוב.');});
Promise.all([import('./render3d.js'),import('./brass-asset.js').then(m=>m.loadBrassAsset()).catch(err=>console.warn('Brass asset unavailable; retaining procedural actor',err))]).then(([{BattleView}])=>{try{view3d=new BattleView(game?$('battleScene'):$('homeScene'));view3d.cameraMode=cameraChoice;view3d.setPresentationQuality(presentationChoice);$('cameraMode').disabled=false;document.body.classList.add('has-3d');try{for(let i=0;i<HEROES.length;i++)portraitCache.set(HEROES[i].id,view3d.capturePortrait(i));lobby();}catch(err){console.warn('Model portraits unavailable; keeping reference art',err)}if(shopTab==='heroes'&&heroDetail&&!$('shop').classList.contains('hidden'))lobby();view3d.renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();pause();toast('התצוגה נעצרה. רענון הדף יטען אותה מחדש.');});}catch(err){console.warn('3D unavailable; using 2D fallback',err)}}).catch(err=>console.warn('3D unavailable',err));
lobby();requestAnimationFrame(loop);

